/* ── Reset ──────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #f4f5f7;
  color: #1a1a1a;
  line-height: 1.5;
}
a { color: inherit; text-decoration: none; }

/* ── Header ─────────────────────────────────────────────────────────────── */
.site-header {
  background: #16213e;
  color: #fff;
  padding: 0.75rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}
.site-title {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #fff;
}
.header-actions { display: flex; align-items: center; gap: 0.75rem; }

.btn {
  padding: 0.375rem 0.875rem;
  border-radius: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 500;
  border: 1px solid rgba(255,255,255,0.25);
  background: rgba(255,255,255,0.1);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s;
}
.btn:hover { background: rgba(255,255,255,0.2); }

/* ── Main ───────────────────────────────────────────────────────────────── */
.site-main { max-width: 1200px; margin: 0 auto; padding: 1.5rem 1.25rem; }

/* ── Filter bar ─────────────────────────────────────────────────────────── */
.filter-bar {
  display: flex;
  gap: 0.625rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}
.input-search {
  flex: 1;
  min-width: 180px;
  padding: 0.5rem 0.75rem;
  border: 1px solid #dde0e6;
  border-radius: 0.375rem;
  font-size: 0.9375rem;
  background: #fff;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.input-search:focus {
  outline: none;
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79,70,229,0.12);
}
.input-select {
  padding: 0.5rem 0.75rem;
  border: 1px solid #dde0e6;
  border-radius: 0.375rem;
  font-size: 0.9375rem;
  background: #fff;
  cursor: pointer;
  transition: border-color 0.15s;
}
.input-select:focus {
  outline: none;
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79,70,229,0.12);
}

/* ── Results count ──────────────────────────────────────────────────────── */
.results-count { color: #6b7280; font-size: 0.8125rem; margin-bottom: 1rem; }

/* ── Game grid ──────────────────────────────────────────────────────────── */
.game-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 1rem;
}
.no-results {
  color: #9ca3af;
  grid-column: 1 / -1;
  padding: 3rem;
  text-align: center;
  font-size: 0.9375rem;
}

