.score-sm { min-width: 1.75rem; height: 1.75rem; font-size: 0.8125rem; }
.score-great { background: #2e7d32; }
.score-mixed { background: #e65100; }
.score-bad   { background: #c62828; }
.score-na    { background: #9ca3af; }

/* ── Platform chips ─────────────────────────────────────────────────────── */
.platforms {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  margin-top: auto;
