_FINDER = "https://backend.metacritic.com/finder/metacritic/web"
_BASE_PARAMS = {
    "componentType": "ProductList",
    "mcoTypeId": "13",
    "sortBy": "-releaseDate",
}


def _items(data: dict) -> list[dict]:
    return data.get("data", {}).get("items", []) or []


