    """First `limit` scored games from the New Releases carousel."""
    data = client.get_json(_FINDER, {
        **_BASE_PARAMS,
        "componentName": "new-releases-carousel",
        "metaScoreMin": "1",
        "offset": "0",
        "limit": str(limit),
